        return out
    # Compare the first and last separated pattern bands cell-by-cell.
    bands = []
    start = prev = occupied_rows[0]
    for r in occupied_rows[1:]:
        if r != prev + 1:
            bands.append((start, prev + 1))
            start = r
        prev = r
    bands.append((start, prev + 1))
    if len(bands) < 2:
        return out
    a0, a1 = bands[0]
    b0, b1 = bands[-1]
    if a1 - a0 != b1 - b0:
        return out
    for dr in range(a1 - a0):
        for c in range(min(len(grid[a0 + dr]), len(grid[b0 + dr]))):
            if grid[a0 + dr][c] == bg and grid[b0 + dr][c] != bg:
                out[a0 + dr][c] = 1
    return out

