from collections import Counter
for p,t,b,n,expected in [
('/tmp/demo1full.txt',3,10,4,{(4,11),(4,12),(5,11),(5,12),(6,11),(6,12)}),
('/tmp/demo2full.txt',3,13,5,{(4,12)}),
('/tmp/demo3in.txt',3,7,2,{(7,c) for c in range(15,28)}|{(8,c) for c in [17,20,23,26]}),
]:
 g=[list(map(int,l.split())) for l in open(p).read().splitlines()]; bg=Counter(x for row in g for x in row).most_common(1)[0][0]
 scores=[]
 for dx in range(-10,11):
  eq=tot=one=zero=0
  # compare top cell c to bottom c+dx
  for k in range(n):
   for c in range(len(g[0])):
    j=c+dx
    if 0<=j<len(g[0]):
     a=g[t+k][c]!=bg; b1=g[b+k][j]!=bg
     tot+=1; eq += a==b1; one+=a and not b1;zero+=b1 and not a
  scores.append((eq/tot,dx,eq,tot,one,zero))
 best=sorted(scores,reverse=True)[:4]
 print('\n',p,'best',best)
 for sc,dx,eq,tot,upper_only,lower_only in best[:1]:
  ch=set()
  for k in range(n):
   for c,v in enumerate(g[t+k]):
    j=c+dx
    if 0<=j<len(g[0]) and v!=bg and g[b+k][j]==bg:ch.add((b+k,j))
  exp_bottom={(r,c) for r,c in expected if r>=b}
  exp_top={(r,c) for r,c in expected if r<t+n}
  print('from top to bottom diffs',ch,'exp bottom',exp_bottom)
  ch2=set()
  for k in range(n):
   for c,v in enumerate(g[b+k]):
    j=c-dx
    if 0<=j<len(g[0]) and v!=bg and g[t+k][j]==bg:ch2.add((t+k,j))
  print('from bottom to top',ch2,'exp top',exp_top)

